use vstd::prelude::*;
use vstd::vec::*;

verus! {

/// Returns all non-empty prefixes of the input sequence.
/// For input of length n, returns n prefixes where the i-th prefix
/// (0-indexed) contains the first i+1 characters of the input.
/// Empty input returns empty result.
#[verifier::spec]
pub spec fn all_prefixes_spec(s: Seq<char>) -> Seq<Seq<char>> {
    let n = s.len();
    Seq::new(n, |i: int| s.subrange(0, i + 1))
}

/// Implementation of all_prefixes with verification.
pub fn all_prefixes(s: Vec<char>) -> (result: Vec<Vec<char>>)
    ensures
        result@ == all_prefixes_spec(s@),
{
    let mut result = Vec::new();
    let mut current_prefix = Vec::new();
    let n = s.len();
    
    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            result.len() == i,
            current_prefix.len() == i,
            forall |k: int| 0 <= k < i ==> result@[k]@ == s@.subrange(0, k + 1),
            forall |k: int| 0 <= k < i ==> current_prefix@ == s@.subrange(0, i),
    {
        current_prefix.push(s[i]);
        let prefix_copy = current_prefix.clone();
        result.push(prefix_copy);
        
        i = i + 1;
    }
    
    result
}

#[test]
fn test_all_prefixes() {
    let empty: Vec<char> = Vec::new();
    let result1 = all_prefixes(empty);
    assert(result1.is_empty());
    
    let single = vec!['a'];
    let result2 = all_prefixes(single);
    assert(result2.len() == 1);
    assert(result2[0]@ == seq!['a']);
    
    let multi = vec!['a', 'b', 'c'];
    let result3 = all_prefixes(multi);
    assert(result3.len() == 3);
    assert(result3[0]@ == seq!['a']);
    assert(result3[1]@ == seq!['a', 'b']);
    assert(result3[2]@ == seq!['a', 'b', 'c']);
}

}